function build_deltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const budget = multiset_diff(before.budget, after.budget);
  const spend = multiset_diff(before.spend, after.spend);
  return {
    rels: [
      { rel: "budget", add: budget.add, del: budget.del },
      { rel: "spend", add: spend.add, del: spend.del },
    ],
    carry_pending: false,
  };
}

